[K-Doctor 전문과목 피부과 v0.1 적용]

[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-dermatology",
  "answer": "등의 색소 병변이 커지고 경계·색이 불규칙해졌으며 과거 출혈력이 있다면, 흑색종(및 기타 악성 색소 병변)을 배제할 수 없어 자가 관찰이 아니라 조속한 대면 진료(피부확대경·필요시 조직검사) 대상입니다. 다만 연령·성별·발병시점·크기·변화 속도가 없어 지금은 '악성 배제 불가, 진행 속도에 따라 응급도 결정'이 정확한 소견입니다.",
  "red_flag": {
    "present": true,
    "items": [
      { "id": "D9", "evidence": "등 색소 병변의 크기 증가 + 경계·색 불규칙 + 과거 출혈력 (ABCDE 중 B·C·D·E 변화에 해당)", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "악성 흑색종",
      "icd10": "C43",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "크기 증가(진행성), 경계 불규칙, 색 다양/불규칙, 출혈력 — ABCDE 중 4개 이상 해당", "basis": "history" }
      ],
      "against": [
        { "text": "연령·성별·발병시점·병변 직경·변화 속도(수주 vs 수년)·가족력·자외선 노출력·기존 점 여부가 없어 위험도 층화 불가", "basis": "history" },
        { "text": "이미지 관찰 소견(SP-29-IMG)이 입력에 없어 형태학적 확증 없음", "basis": "image" }
      ]
    },
    {
      "name": "기타 악성 색소·각화 병변(편평세포암·기저세포암 색소형, 비정형 지루각화증)",
      "icd10": "C44 / L82",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "성인 등의 변화하는 병변 + 출혈력은 편평세포암·기저세포암·비정형 지루각화증에서도 가능", "basis": "history" }
      ],
      "against": [
        { "text": "표면 인설·궤양·각질·진주양 윤곽 등 형태 소견이 없어 구분 불가", "basis": "image" }
      ]
    },
    {
      "name": "양성 색소 병변의 변화(자극된 지루각화증, 외상성 혈종, 혈관종 등)",
      "icd10": "L82 / D18",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "과거 출혈력은 자극·외상 후 양성 병변에서도 흔함", "basis": "history" }
      ],
      "against": [
        { "text": "경계·색 불규칙 + 크기 증가는 양성으로 단정할 근거가 되지 않음 — 피부 규칙 2·3에 따라 사진·문진만으로 '양성'이라 배제 불가", "basis": "guideline" }
      ]
    }
  ],
  "missing_info": [
    "이 병변이 처음 발견된 시점과 최근 변화 속도(예: 몇 주 안에 커졌는지, 몇 년에 걸쳐 서서히인지) — 자가 관찰과 즉시 내원을 가르는 가장 판별력 큰 한 가지 질문"
  ],
  "suggested_tests": [
    { "name": "대면 피부과 진료 + 피부확대경(dermoscopy) 검사", "purpose": "색소 병변의 악성/양성 감별 및 조직검사 필요성 판단", "urgency": "24h", "basis": "guideline" },
    { "name": "병변 절제 또는 천자 생검(조직검사)", "purpose": "흑색종 의심 시 확정 진단", "urgency": "24h", "basis": "guideline" }
  ],
  "suggested_treatments": [
    { "kind": "referral", "description": "등 색소 병변의 변화·출혈력은 원격 판단 불가. 피부과 대면 진료로 피부확대경 검사, 필요 시 조직검사. 자가 관찰(집에서 크기·색 사진 비교)은 진료 전까지 변화 추적 목적으로만 권고하며, '변화가 없으니 안심하라'는 의미가 아님.", "basis": "guideline" },
    { "kind": "self_care", "description": "내원 전까지 병변 자극·긁기·문지르기 회피, 출혈 시 소독 후 압박, 병변을 직접 만지지 않기. 크기 비교용으로 투명 자 또는 동전 옆에 두고 동일 조명·각도로 사진 촬영(2주 간격). 햇빛 노출 시 자외선 차단.", "basis": "history" }
  ],
  "handoff": { "better_specialty": "", "reason": "" },
  "confidence": { "clinical": 4, "information": 2 },
  "warnings": [
    "피부 규칙 2: 피부암 가능성은 사진·문진만으로 '아니다'라고 배제하지 않는다. 변화가 있는 색소 병변은 이미지 품질과 무관하게 대면 진료(피부확대경·필요시 조직검사) 대상.",
    "피부 규칙 3: 이 병변을 '양성'이라 표현하지 않는다. 입력 정보로는 흑색종을 포함한 악성 병변을 배제할 수 없다.",
    "입력에 연령·성별·발병시점·크기·변화 속도·가족력·자외선 노출력·기존 점의 변화 여부가 없어 위험도 층화와 확신도 산정이 제한됨(information 2).",
    "즉시 응급(119·응급실) 수준 위험 신호(D1~D8)는 이 입력에서 확인되지 않음. 다만 아래 자가 관찰 vs 즉시 내원 분기 기준에 해당하면 응급도가 올라간다."
  ],
  "clinical_reasoning_notes": {
    "즉시 내원(수일 내, urgent)으로 전환해야 하는 핵심 소견": [
      "최근 수주 이내 뚜렷한 크기 증가(더 빠르면 더 위험)",
      "경계의 불규칙화, 색조가 3가지 이상(검정·갈색·붉은색·회색·흰색) 혼재",
      "자발 출혈·궤양·딱지·진물, 통증·가려움의 새 발생",
      "주변에 위성(satellite) 병변 또는 위로 솟은 결절(nodular) 변화",
      "손발바닥·손발톱 아래(acral·subungual) 색소 띠 또는 조갑주름 색소 침범(Hutchinson sign)",
      "면역억제 상태, 흑색종 가족력, 다수의 비정형 점"
    ],
    "즉시 응급(119·응급실)으로 전환해야 하는 소견": [
      "병변에서 지속적·다량 출혈, 또는 전신 증상(발열·체중 감소·림프절 종대 동반) — 전신 평가 필요"
    ],
    "단기 자가 관찰이 허용되는 조건(제한적, 예외적)": [
      "병변이 수년간 크기·색·경계 변화가 없음이 사진으로 확인되고, 출혈이 최근 외상 1회성이며 2~3일 내 자연 소실, 다른 위험 신호 없음",
      "이 경우에도 2~4주 내 피부과 외래 예약을 병행해야 함. 완전한 자가 관찰만으로 종결하지 않음"
    ],
    "다음 한 가지만 더 확인하면 분기가 갈린다": [
      "변화가 '얼마나 짧은 기간에' 일어났는가(수주 vs 수년). 짧을수록 악성 가능성↑, 진료 우선순위↑"
    ]
  }
}
[/SPECIALIST_FINDING]

자기 점검: C1 위반 없음(RED_FLAG = D9). C2 위반 없음(모든 항목 basis 명시). C3 위반 없음('양성'·'확정 진단' 표현 회피, 피부 규칙 3 준수). C4 위반 없음(용량 서술 없음). C5 준수(H-2 위험 신호·H-3 형태학 틀 점검). C6 해당 없음(연령 미상 — 소아 가능성 있으면 kdoctor-pediatrics 병기 필요). C7 준수(각 가설 against 제시 + 양성 배제 근거 반증).

주의: 이 소견은 전문의 검토 전 초안 SP 기준이며, 실제 진료를 대체하지 않습니다.
